BILINGUAL.EN:
Now lets formalize the process in terms of functions. We start with a value for the radicand radicand (the number whose square root we are trying to compute) and a value for the guess. If the guess is good enough for our purposes, we are done; if not, we must repeat the process with an improved guess. We write this basic strategy as a
procedure:
function:

SNIPPET.JAVASCRIPT:
function sqrt_iter(guess, x) {
    return is_good_enough(guess, x)
           ? guess
           : sqrt_iter(improve(guess, x), x);
}

function improve(guess, x) {
    return average(guess, x / guess);
}

function is_good_enough(guess, x) {
    return abs(square(guess) - x) < 0.001;
}

function conditional(predicate, then_clause, else_clause) {		    
    return predicate ? then_clause : else_clause;
}

function sqrt_iter(guess, x) {
    return conditional(is_good_enough(guess, x),
                       guess,
                       sqrt_iter(improve(guess, x),
                                 x));
}

const relative_tolerance = 0.0001;
function is_good_enough(guess, x) {
    return abs(square(guess) - x) < guess * relative_tolerance;
}

function is_good_enough(guess, x) {
    return abs(cube(guess) - x) < 0.001;
}
function div3(x, y) {
     return (x + y) / 3;
}
function improve(guess, x) {
    return div3(x / (guess * guess), 2 * guess);
}
function cube_root(guess, x) {
    return is_good_enough(guess, x)
           ? guess
           : cube_root(improve(guess, x), x);
}
